<!DOCTYPE html><html><head><meta charset="utf-8"><title>Invoice <?= e($o->order_no) ?></title>
<style>body{font-family:Inter,Arial,sans-serif;color:#111;max-width:820px;margin:30px auto;padding:0 20px;font-size:14px}h1{font-family:Georgia,serif;letter-spacing:.14em;margin:0}table{width:100%;border-collapse:collapse;margin-top:24px}th{text-align:left;border-bottom:2px solid #111;padding:8px 6px;font-size:12px;text-transform:uppercase;letter-spacing:.08em}td{padding:10px 6px;border-bottom:1px solid #ddd}.r{text-align:right}.tot td{border:0;padding:4px 6px}@media print{button{display:none}}</style></head><body>
<div style="display:flex;justify-content:space-between;align-items:flex-start"><div><h1><?= e(setting('site_name', 'DRESSY')) ?></h1><div style="color:#666;margin-top:6px"><?= e(setting('contact_address')) ?><br><?= e(setting('contact_phone')) ?> &middot; <?= e(setting('contact_email')) ?></div></div>
<div class="r"><b style="font-size:20px">INVOICE</b><br><?= e($o->order_no) ?><br><?= date('d M Y', strtotime($o->created_at)) ?><br><button onclick="window.print()" style="margin-top:8px;padding:6px 14px">Print</button></div></div>
<div style="margin-top:26px"><b>Bill / ship to</b><br><?= e($o->name) ?><br><?= e($o->address) ?>, <?= e($o->city) ?> <?= e($o->postal_code) ?><br><?= e($o->country) ?><br><?= e($o->phone) ?></div>
<table><tr><th>Item</th><th class="r">Price</th><th class="r">Qty</th><th class="r">Total</th></tr>
<?php foreach ($items as $it): $meta = $it->meta ? json_decode($it->meta, true) : null; ?><tr><td><?= e($it->name) ?><?= $it->size ? ' - ' . e($it->size) : '' ?><?= $it->color ? ' / ' . e($it->color) : '' ?><?php if ($meta && !empty($meta['lines'])) foreach ($meta['lines'] as $l): ?><br><small style="color:#666"><?= e($l['label']) ?> (<?= e($l['color']) ?><?= $l['size'] ? ', ' . e($l['size']) : '' ?>)</small><?php endforeach; ?></td><td class="r"><?= money($it->price) ?></td><td class="r"><?= (int)$it->qty ?></td><td class="r"><?= money($it->line_total) ?></td></tr><?php endforeach; ?></table>
<table class="tot" style="width:300px;margin-left:auto"><tr><td>Subtotal</td><td class="r"><?= money($o->subtotal) ?></td></tr><?php if ($o->discount > 0): ?><tr><td>Discount</td><td class="r">-<?= money($o->discount) ?></td></tr><?php endif; ?><tr><td>Shipping</td><td class="r"><?= $o->shipping > 0 ? money($o->shipping) : 'Free' ?></td></tr><tr><td><b>Total</b></td><td class="r"><b><?= money($o->total) ?></b></td></tr><tr><td>Payment</td><td class="r"><?= e(strtoupper($o->payment_method)) ?> - <?= e(ucfirst($o->payment_status)) ?></td></tr></table>
<p style="margin-top:40px;color:#666;text-align:center">Thank you for shopping with <?= e(setting('site_name', 'DRESSY')) ?>.</p></body></html>
